package com.reqlens.app;
import android.app.*;import android.graphics.Typeface;import android.os.Bundle;import android.widget.*;import java.util.*;
public final class MultiResponseCompareActivity extends Activity{
 private Spinner tabs;private TextView out;private List<RepeaterTabRepository.Tab>items;
 @Override public void onCreate(Bundle b){super.onCreate(b);items=RepeaterTabRepository.snapshot();LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(16,16,16,16);TextView t=new TextView(this);t.setText("Multi-response Compare");t.setTextSize(22);t.setTypeface(Typeface.DEFAULT_BOLD);r.addView(t);tabs=new Spinner(this);tabs.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,items));r.addView(tabs);Button run=new Button(this);run.setText("ANALYZE TAB HISTORY");run.setOnClickListener(v->analyze());r.addView(run);out=new TextView(this);out.setTypeface(Typeface.MONOSPACE);out.setTextIsSelectable(true);ScrollView s=new ScrollView(this);s.addView(out);r.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);}
 private void analyze(){RepeaterTabRepository.Tab t=(RepeaterTabRepository.Tab)tabs.getSelectedItem();if(t==null||t.history.isEmpty()){out.setText("No response history in this tab");return;}StringBuilder s=new StringBuilder("#  status  bytes  time\n");long total=0;int min=Integer.MAX_VALUE,max=0;Map<Integer,Integer>codes=new TreeMap<>();for(int i=0;i<t.history.size();i++){RequestRecord r=t.history.get(i);int n=r.responseBody==null?0:r.responseBody.length();min=Math.min(min,n);max=Math.max(max,n);total+=r.durationMs;codes.merge(r.statusCode,1,Integer::sum);s.append(i+1).append("  ").append(r.statusCode).append("  ").append(n).append("  ").append(r.durationMs).append("ms\n");}s.append("\nresponses=").append(t.history.size()).append(" avgTime=").append(total/t.history.size()).append("ms sizeRange=").append(min).append("..").append(max).append(" statuses=").append(codes);out.setText(s.toString());}
}
